{
    "name": "numbat-vscode-extension",
    "displayName": "Numbat",
    "description": "Syntax highlighting for the Numbat programming language",
    "version": "0.1.1",
    "license": "(MIT OR Apache-2.0)",
    "icon": "./assets/numbat-256x256.png",
    "engines": {
        "vscode": "^1.71.0"
    },
    "categories": [
        "Programming Languages"
    ],
    "keywords": [
        "language",
        "physics",
        "units",
        "calculation"
    ],
    "contributes": {
        "languages": [{
            "id": "numbat",
            "aliases": ["Numbat", "numbat"],
            "extensions": [".nbt"],
            "configuration": "./language-configuration.json",
            "icon": {
                "light": "./assets/numbat-64x64.png",
                "dark": "./assets/numbat-64x64.png"
            }
        }],
        "grammars": [{
            "language": "numbat",
            "scopeName": "source.numbat",
            "path": "./syntaxes/numbat.tmLanguage.json"
        }]
    },
    "scripts": {
        "vscode:package": "vsce package"
    },
    "devDependencies": {
        "@vscode/vsce": "3.3.2"
    },
    "vsce": {
        "skipLicense": true
    },
    "repository": {
        "type": "git",
        "url": "https://github.com/sharkdp/numbat.git"
    },
    "homepage": "https://github.com/sharkdp/numbat/blob/main/vscode-extension/README.md"
}

import java.util.Properties

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("rust")
}

val tauriProperties = Properties().apply {
    val propFile = file("tauri.properties")
    if (propFile.exists()) {
        propFile.inputStream().use { load(it) }
    }
}

android {
    compileSdk = 36
    namespace = "fish.shark.numbat"

    signingConfigs {
        create("release") {
            storeFile = file(System.getenv("KEYSTORE_PATH") ?: "")
            storePassword = System.getenv("KEYSTORE_PASSWORD") ?: ""
            keyAlias = System.getenv("KEY_ALIAS") ?: "numbat"
            keyPassword = System.getenv("KEY_PASSWORD") ?: ""
        }
    }

    defaultConfig {
        manifestPlaceholders["usesCleartextTraffic"] = "false"
        applicationId = "fish.shark.numbat"
        minSdk = 24
        targetSdk = 36
        versionCode = tauriProperties.getProperty("tauri.android.versionCode", "1").toInt()
        versionName = tauriProperties.getProperty("tauri.android.versionName", "1.0")
    }
    buildTypes {
        getByName("debug") {
            manifestPlaceholders["usesCleartextTraffic"] = "true"
            isDebuggable = true
            isJniDebuggable = true
            isMinifyEnabled = false
            packaging {                jniLibs.keepDebugSymbols.add("*/arm64-v8a/*.so")
                jniLibs.keepDebugSymbols.add("*/armeabi-v7a/*.so")
                jniLibs.keepDebugSymbols.add("*/x86/*.so")
                jniLibs.keepDebugSymbols.add("*/x86_64/*.so")
            }
        }
        getByName("release") {
            signingConfig = signingConfigs.getByName("release")
            isMinifyEnabled = true
            proguardFiles(
                *fileTree(".") { include("**/*.pro") }
                    .plus(getDefaultProguardFile("proguard-android-optimize.txt"))
                    .toList().toTypedArray()
            )
        }
    }
    kotlinOptions {
        jvmTarget = "1.8"
    }
    buildFeatures {
        buildConfig = true
    }
}

rust {
    rootDirRel = "../../../"
}

dependencies {
    implementation("androidx.webkit:webkit:1.14.0")
    implementation("androidx.appcompat:appcompat:1.7.1")
    implementation("androidx.activity:activity-ktx:1.10.1")
    implementation("com.google.android.material:material:1.12.0")
    testImplementation("junit:junit:4.13.2")
    androidTestImplementation("androidx.test.ext:junit:1.1.4")
    androidTestImplementation("androidx.test.espresso:espresso-core:3.5.0")
}

apply(from = "tauri.build.gradle.kts")

buildscript {
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        classpath("com.android.tools.build:gradle:8.11.0")
        classpath("org.jetbrains.kotlin:kotlin-gradle-plugin:1.9.25")
    }
}

allprojects {
    repositories {
        google()
        mavenCentral()
    }
}

tasks.register("clean").configure {
    delete("build")
}

name: CI

on: [push, pull_request]

jobs:
  build:
    strategy:
      fail-fast: false
      matrix:
        job:
          # Linux
          - { os: ubuntu-24.04, compiler: "g++",     cpp_standard: "11", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "g++",     cpp_standard: "14", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "g++",     cpp_standard: "17", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "g++",     cpp_standard: "17", build_type: "RelWithDebInfo" }
          - { os: ubuntu-24.04, compiler: "g++",     cpp_standard: "20", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "clang++", cpp_standard: "11", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "clang++", cpp_standard: "14", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "clang++", cpp_standard: "17", build_type: "Debug"          }
          - { os: ubuntu-24.04, compiler: "clang++", cpp_standard: "17", build_type: "RelWithDebInfo" }
          - { os: ubuntu-24.04, compiler: "clang++", cpp_standard: "20", build_type: "Debug"          }
          # MacOS
          - { os: macos-15,     compiler: "clang++", cpp_standard: "17", build_type: "Debug"          }
          # Windows
          # Note: we do not test for C++11 as MSVC does not support a C++11 version switch, see:
          # https://devblogs.microsoft.com/cppblog/msvc-now-correctly-reports-__cplusplus/
          - { os: windows-2022, compiler: "cl",      cpp_standard: "14", build_type: "Debug"          }
          - { os: windows-2022, compiler: "cl",      cpp_standard: "17", build_type: "Debug"          }
          - { os: windows-2022, compiler: "cl",      cpp_standard: "17", build_type: "RelWithDebInfo" }
          - { os: windows-2022, compiler: "cl",      cpp_standard: "20", build_type: "Debug"          }

    runs-on: ${{ matrix.job.os }}

    steps:
    - uses: actions/checkout@v4
      with:
        submodules: true

    - name: Configure CMake
      shell: bash
      run: |
        cmake -B build -S $GITHUB_WORKSPACE \
          -DCMAKE_CXX_COMPILER=${{matrix.job.compiler}} \
          -DCMAKE_CXX_STANDARD=${{matrix.job.cpp_standard}} \
          -DCMAKE_CXX_STANDARD_REQUIRED=ON \
          -DCMAKE_BUILD_TYPE=${{matrix.job.build_type}}

    - name: Build
      shell: bash
      run: cmake --build build --config ${{matrix.job.build_type}}

    - name: "Copy executables"
      if: runner.os == 'Windows'
      shell: bash
      run: cp build/${{matrix.job.build_type}}/*.exe build/

    - name: Run example
      shell: bash
      run: ./build/dbg_macro-example

    - name: Run demo
      shell: bash
      run: ./build/dbg_macro-demo

    - name: Run tests
      shell: bash
      run: ./build/dbg_macro-tests

    - name: Run tests (macro disabled)
      shell: bash
      run: ./build/dbg_macro-tests-macro_disabled

